  });

  @override
  int get hashCode =>
      kind.hashCode ^
      generation.hashCode ^
      requestId.hashCode ^
      text.hashCode ^
      detail.hashCode ^
      rttMicros.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeEvent &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          generation == other.generation &&
          requestId == other.requestId &&
          text == other.text &&
          detail == other.detail &&
          rttMicros == other.rttMicros;
}

